      /** @arg {CodeMirrorV} cm @arg {ExParams} params*/
      omap: function(cm, params) { this.map(cm, params, 'operatorPending'); },
      /** @arg {CodeMirrorV} cm @arg {ExParams} params*/
      noremap: function(cm, params) { this.map(cm, params, undefined, true); },
      /** @arg {CodeMirrorV} cm @arg {ExParams} params*/
